export const LECTURES_DATA: Record<string, any> = {
  "1-1-1": {},
  "1-1-1-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 1.1: Your First Blink\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Introduction</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will build your first working <strong>ESP32</strong> program.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will control a small LED using blocks and make it turn ON. This is the first time you will see how instructions you create in the system directly affect a physical (or simulated) <strong>output</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to make the LED turn on, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The output changes based on your instructions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a complete working cycle of <strong>input</strong> instructions that produce visible behaviour.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.1/LEVEL 1.1 Introduction/images/misc_0.png\" alt=\"LEVEL 1.1: Your First Blink\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "1-1-1-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 1.1: Your First Blink\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is <strong>ESP32</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> is a small programmable <strong>microcontroller</strong>. A <strong>microcontroller</strong> is a compact computing device designed to interact with physical components such as lights, sensors, and motors.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> can also be called a mini version of a computer as it is a compact computer that has been designed for tasks that require specific control and instructions.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Unlike a normal computer, which is designed for general-purpose tasks like browsing or running applications, the <strong>ESP32</strong> is designed for control tasks.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Its main purpose is to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Receive instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Execute those instructions repeatedly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control physical outputs based on those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Read inputs from the environment</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, the <strong>ESP32</strong> is being used as a controller for an LED.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What are Blocks?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this system, you are not writing traditional code. Instead, you are using blocks.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each block represents a specific instruction that the <strong>ESP32</strong> understands.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A block can set a pin mode</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A block can turn a signal ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A block can turn a signal OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A block can introduce a delay</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Blocks are executed in sequence from top to bottom. This means the order in which you arrange them matters.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This block-based interface al<strong>low</strong>s you to create programs visually by linking blocks together, much like assembling building pieces. Each block represents a specific instruction that the <strong>ESP32</strong> can understand, and the system automatically translates your block arrangement into executable code.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This approach is designed to make programming more intuitive, especially for beginners, by removing the need to memorize syntax and instead focusing on logic and program f<strong>low</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">To use it, you simply select the required block from the sidebar and drag it into the workspace, placing it where you want it to connect.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is a <strong>Pin</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>pin</strong> is a physical connection point on the <strong>ESP32</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each <strong>pin</strong> can be thought of as a control interface between the <strong>ESP32</strong> and external components.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Pins</strong> can:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Send electrical signals (output)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Receive electrical signals (input)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, we use a <strong>pin</strong> as an <strong>output</strong> to control an LED.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When a <strong>pin</strong> is connected to an LED:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 controls whether electricity flows to the LED</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This determines whether the LED turns ON or OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Why do we set <strong>Pin</strong> Mode?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Before using a <strong>pin</strong>, we must define its behaviour.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is done using “Set <strong>Pin</strong> Mode”.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>pin</strong> can operate in different modes, but in this lesson, we only use:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output Mode</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Output</strong> mode means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 will send signals out through the pin</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It will control external components like LEDs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without setting <strong>pin</strong> mode correctly:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 may not behave as expected</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The pin may not respond properly to output commands</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This step is required because the <strong>ESP32</strong> needs to know how each <strong>pin</strong> will be used before executing instructions.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is Digital Write (<strong>HIGH</strong> and <strong>LOW</strong>)?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Digital signals have only two states:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">HIGH and LOW</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>HIGH</strong> means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Electrical signal is ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Current flows through the pin</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED turns ON</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>LOW</strong> means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Electrical signal is OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">No current flows through the pin</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED turns OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is called digital control because it uses only two values instead of a range of values.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are essentially switching electricity on and off through instructions.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What actually happens when your program runs?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you connect your blocks, the <strong>ESP32</strong> executes them in order.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Step-by-step process:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 reads the first block</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It sets the pin mode to output</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It moves to the next block and turns the LED ON that is connected at <strong>Pin</strong> 2.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It moves to next block, and turns the LED OFF that is connect at <strong>Pin</strong> 2.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This repetition is automatic and built into the system.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Even though you only created the sequence once, the <strong>ESP32</strong> keeps running it repeatedly.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is why the LED keeps blinking.</p>\n            <div class=\"my-4 flex items-start gap-3 rounded-xl border border-indigo-100 bg-indigo-50/50 p-4 text-sm text-indigo-900 shadow-sm\">\n              <span class=\"text-lg flex-shrink-0\">💡</span>\n              <div class=\"flex-1 leading-relaxed\">Remember: Here we are using blocks to simplify the coding complexity and it translates to real code which you will learn bit by bit.</div>\n            </div>\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Key Insight of This Lesson</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are not manually repeating actions. The system is repeating them for you.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Your block sequence becomes a cycle that runs continuously.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is the foundation of all embedded systems behaviour.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.1/LEVEL 1.1 Concept Building/images/misc_0.jpg\" alt=\"LEVEL 1.1: Your First Blink\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "1-1-2": {},
  "1-1-2-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 1.2: Making Changes Visible (Using Delay)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Introduction</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous lesson, you controlled an LED by turning it ON and OFF using blocks.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">However, you may have noticed something unusual:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Even though you gave instructions to turn the LED ON and then OFF, it was difficult to clearly see both actions.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This happens because the <strong>ESP32</strong> executes instructions extremely fast.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to s<strong>low</strong> down the execution so that changes become visible and easier to understand.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.2/Introduction/images/misc_0.png\" alt=\"LEVEL 1.2: Making Changes Visible (Using Delay)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "1-1-2-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 1.2: Making Changes Visible (Using Delay)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Why couldn’t you clearly see the ON and OFF?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous lesson, when you turned the LED ON and then OFF, both actions happened almost instantly.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> executes instructions extremely fast—far faster than the human eye can detect changes.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Because of this:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED turns ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Then immediately turns OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">And then immediately turns back ON</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These two actions happen so quickly that they appear as if they happened at the same time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">To you, it may look like:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Nothing happened</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">or</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED did not turn OFF properly</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">However, this is not the case. The <strong>ESP32</strong> correctly executed both instructions. The change simply occurred too quickly to be observed by the human eye.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This <strong>high</strong>lights an important idea:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The system is working correctly, but the result is not always visible to us.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.2/Concept Building/images/misc_0.png\" alt=\"LEVEL 1.2: Making Changes Visible (Using Delay)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is Delay?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Delay</strong> is used to pause the execution of the program for a specific amount of time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When the <strong>ESP32</strong> reaches a <strong>Delay</strong> block, it temporarily stops executing further instructions before moving to the next step.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This pause gives enough time for the current action to be observed.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Delay</strong> is measured in milliseconds:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">1000 milliseconds = 1 second</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">500 milliseconds = half a second</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">2000 milliseconds = 2 seconds</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s you to control how long the system should wait before continuing.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.2/Concept Building/images/What_is_Delay__0.png\" alt=\"What is Delay?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Why do we need Delay?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">We use <strong>delay</strong> to make changes visible and understandable.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without <strong>delay</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Instructions execute almost instantly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Changes happen too quickly to observe</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The result may appear incorrect or confusing</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">With <strong>delay</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system pauses between actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Each step becomes clearly visible</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can understand what each instruction is doing</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">If you:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Add a delay</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Then:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED remains ON for a short period</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can clearly see the ON state before it turns OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes the behavior of the system easier to understand.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.2/Concept Building/images/Why_do_we_need_Delay__0.png\" alt=\"Why do we need Delay?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Understanding time and observation\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Computers are designed to operate at extremely <strong>high</strong> speeds.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">They can perform thousands or even millions of operations in a very short amount of time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Humans, on the other hand, require time to notice and understand changes.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a gap between:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Machine speed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Human perception</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Delay</strong> acts as a bridge between these two.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It s<strong>low</strong>s down execution so that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Each step becomes observable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Each instruction becomes meaningful</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without <strong>delay</strong>, it becomes difficult to understand what the system is doing.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.2/Concept Building/images/Understanding_time_and_observation_0.png\" alt=\"Understanding time and observation\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What actually happens when Delay is used?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When the <strong>ESP32</strong> runs your program with <strong>delay</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It executes the first instruction</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It reaches the Delay block</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It pauses for the specified amount of time</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">After the pause, it continues to the next instruction</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This process continues until all instructions are completed</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">During the <strong>delay</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">No new instructions are executed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The current state remains unchanged</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This pause al<strong>low</strong>s you to clearly observe the effect of each instruction before moving on.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.2/Concept Building/images/What_actually_happens_when_Delay_is_used__0.png\" alt=\"What actually happens when Delay is used?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes instructions very quickly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Rapid changes may not be visible to the human eye</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Delay introduces a pause between instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This pause makes system behavior easier to observe</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Delay does not change the logic of the program</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It only changes the timing of execution</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    ",
  "1-1-3": {},
  "1-1-3-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous lessons, you controlled an LED and learned how <strong>delay</strong> helps make changes visible.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now, it is time to understand something deeper:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">How does the <strong>ESP32</strong> actually fol<strong>low</strong> your instructions?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you connect multiple blocks together:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Does everything happen at once?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Or does the <strong>ESP32</strong> fol<strong>low</strong> a specific order?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how the <strong>ESP32</strong> reads and executes your program step by step.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "1-1-3-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/Why_order_matters_so_much_1.png\" alt=\"Concept Building\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How does the ESP32 read your program?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you build a program using blocks, it may feel like you are creating one complete system where everything happens together.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">But the ESP32 does not see your program as a “whole idea.”</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead, it treats it as a strict sequence of steps that must be fol<strong>low</strong>ed one after another.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It begins from the first block, executes it completely, then moves to the next one, and continues until it reaches the end.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It does not:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Look ahead to future blocks</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Rearrange your logic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Skip instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Try to understand your intention</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It simply fol<strong>low</strong>s exactly what you placed, in the exact order you placed it.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is the foundation of how every <strong>ESP32</strong> program behaves.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/How_does_the_ESP32_read_your_program__0.png\" alt=\"How does the ESP32 read your program?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Why order matters so much\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Take a simple set of blocks controlling an LED:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">If you arrange them like:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Wait</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The behavior will fol<strong>low</strong> that exact order:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED turns ON first</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It stays ON for some time</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Then it turns OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now if you change only the order:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Wait</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED ON</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The behavior changes completely:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED starts OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Then turns ON after the delay</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Nothing in the blocks changed except their order—but the result is different.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is because in programming, order is not just structure—it defines behavior.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/Why_order_matters_so_much_0.png\" alt=\"Why order matters so much\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Understanding blocks as individual actions\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each block represents a single, direct action.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A HIGH block does one thing: it turns the LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A LOW block does one thing: it turns the LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A Delay block does one thing: it pauses execution</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> does not combine these actions or process them in parallel.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It performs them one at a time, fully completing one before moving to the next.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes behavior predictable:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">One block → one action → immediate effect</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/Understanding_blocks_as_individual_actions_0.png\" alt=\"Understanding blocks as individual actions\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Understanding the idea of state\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">At any moment, the system is in a condition called a state.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For an LED, the state is very simple:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Only one state can exist at a time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each action you give changes this state.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">HIGH changes the state to ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LOW changes the state to OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When a new instruction is executed, it replaces whatever state existed before.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The system does not remember previous states unless you explicitly design it to do so.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It only reflects the most recent instruction affecting it.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">As the program runs, the system’s state changes step by step.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED becomes ON when a HIGH instruction is executed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It remains ON during a delay</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It changes to OFF when LOW is executed</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a visible progression of states over time.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/Understanding_the_idea_of_state_0.png\" alt=\"Understanding the idea of state\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What actually happens during execution\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you run your program, the <strong>ESP32</strong> fol<strong>low</strong>s a strict execution f<strong>low</strong>:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It starts from the first block and processes each instruction one by one.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">If it encounters a <strong>delay</strong>, it temporarily pauses before continuing.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Once all instructions are completed, execution reaches the end of the sequence.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">At this point, the program does not stop in the traditional sense—it simply finishes that pass of execution.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The final state remains active until another instruction changes it again.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/What_actually_happens_during_execution_0.png\" alt=\"What actually happens during execution\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Understanding behavior over time\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you observe your program over time, you begin to see that behavior is not just about individual instructions, but about how those instructions unfold across time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You start noticing:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">When a change happens</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">How long it lasts</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">What causes the next change</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a relationship between:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Order of instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Timing between actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Visible system behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In other words, programming is not just about what you write, but how those instructions behave over time.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.3/Concept Building/images/Understanding_behavior_over_time_0.png\" alt=\"Understanding behavior over time\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key insight of this lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">At the core of this lesson are a few essential ideas:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes instructions one by one</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The order of instructions directly defines behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Each instruction performs a single, specific action</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Each action changes the system’s state</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system only reflects the most recent change</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Delay affects visibility, not logic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Behavior emerges from sequence, state, and timing working together</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    ",
  "1-1-4": {},
  "1-1-4-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So far, you have learned how to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control an LED</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use delay to make changes visible</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Understand execution order</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Observe repeating behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now it is time to understand something very important:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Why does the program repeat automatically?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Is everything repeated?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Or are some parts executed only once?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how the <strong>ESP32</strong> organizes your program into two main parts:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Setup</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This will help you understand the complete f<strong>low</strong> of how your program runs.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "1-1-4-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/How_Loop_creates_continuous_behavior_1.png\" alt=\"Concept Building\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Does the program run only once?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you build a sequence of blocks, it is natural to assume that the system should:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">execute the instructions once</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">then stop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is how most instructions in daily life work. You give directions, they are completed, and the process ends.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">But when you run your <strong>ESP32</strong> program, something different happens.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">After completing the sequence, the system does not stop. Instead, it immediately starts again from the beginning and executes the same instructions again.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So instead of running once, your program keeps running continuously.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/How_Loop_creates_continuous_behavior_2.png\" alt=\"Does the program run only once?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Why does the ESP32 behave like this?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> is not designed like a calculator that finishes a task and stops.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It is designed for systems that must stay alive and responsive all the time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Think about real-world systems:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Traffic lights cannot stop working after one cycle</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sensors must keep checking values continuously</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Devices must constantly respond to changes</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Because of this, the <strong>ESP32</strong> is built to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">keep executing instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">keep checking conditions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">keep updating outputs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It only stops if it is powered off or reset.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So continuous repetition is not accidental—it is the core design of the system.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/Why_does_the_ESP32_behave_like_this__0.png\" alt=\"Why does the ESP32 behave like this?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How is an ESP32 program structured?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you run your <strong>ESP32</strong> program, it may look like all instructions are working together as one continuous system. But internally, the <strong>ESP32</strong> does not treat your program as a single block of logic.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead, every program is divided into two main sections:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Setup</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These two sections define how the system behaves over time. Some instructions are meant to run only once at the beginning, while others are meant to run repeatedly for as long as the system is active.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Understanding this structure is important because it explains why some actions happen once and others continue forever.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/How_is_an_ESP32_program_structured__0.png\" alt=\"How is an ESP32 program structured?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is Setup?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">At the start of every program, there are certain tasks that prepare the system before anything else happens. These tasks belong to the <strong>Setup</strong> section.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Setup</strong> runs only once when:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program starts</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The device is powered on</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system is reset</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is where the <strong>ESP32</strong> prepares everything it needs before starting continuous operation.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the image are a few blocks that are examples of such instructions that only need to be executed once. The code for them goes in the <strong>setup</strong> method:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example, when you configure a <strong>pin</strong> using “Set <strong>Pin</strong> Mode,” you are defining how that <strong>pin</strong> will behave for the rest of the program. Once this is set, it does not need to be configured again.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Setup</strong> is not concerned with repeating actions. Its purpose is to make sure everything is correctly initialized before the system begins its main behavior.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/What_is_Setup__0.png\" alt=\"What is Setup?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Why Setup runs only once\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Some instructions are meant to define initial conditions rather than ongoing behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">If these instructions were repeated continuously, the system would waste resources doing the same configuration again and again without any benefit.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example, repeatedly setting a <strong>pin</strong> to <strong>OUTPUT</strong> does not change anything after the first time. It simply re-applies the same configuration unnecessarily.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Because of this, <strong>Setup</strong> is designed to execute only once. This ensures:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system starts in a stable state</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">No unnecessary repetition occurs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Processing power is used efficiently</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Once <strong>Setup</strong> finishes its execution, it is not called again during normal operation.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is Loop?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">After <strong>Setup</strong> completes, the <strong>ESP32</strong> does not stop running. Instead, it enters the <strong>Loop</strong> section.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is where the main behavior of the system is defined.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Everything inside the <strong>Loop</strong> is executed continuously. When the <strong>ESP32</strong> reaches the end of the <strong>Loop</strong>, it does not stop. Instead, it automatically goes back to the beginning and starts again.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates an ongoing cycle of execution that continues for as long as the device is powered on.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>Loop</strong> is responsible for:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Continuous actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-time responses</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Ongoing system behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Above is an example of instructions that are repeated for a pattern of blinking LED.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These blocks go into the <strong>loop</strong> section since these are instructions that need to be repeated.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/What_is_Loop__0.png\" alt=\"What is Loop?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How Loop creates continuous behavior\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Inside the <strong>Loop</strong>, you define a sequence of instructions.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Wait</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Wait</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When these instructions are executed, they form one complete cycle of behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Once the <strong>ESP32</strong> reaches the end of this sequence, it immediately starts again from the beginning of the <strong>Loop</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This results in a repeating pattern:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ON → OFF → ON → OFF → ON → OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each repetition is identical because the same instructions are executed in the same order every time.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This repetition is what al<strong>low</strong>s embedded systems to behave continuously instead of performing only one action.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/How_Loop_creates_continuous_behavior_0.png\" alt=\"How Loop creates continuous behavior\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What happens when the program runs\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When the <strong>ESP32</strong> starts running your program, it fol<strong>low</strong>s a fixed execution f<strong>low</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">First, it begins with <strong>Setup</strong>. All instructions inside <strong>Setup</strong> are executed once in order. Once <strong>Setup</strong> is complete, the system transitions into the <strong>Loop</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Inside the <strong>Loop</strong>, instructions are executed one by one. After the last instruction is executed, the <strong>ESP32</strong> does not stop. Instead, it immediately returns to the beginning of the <strong>Loop</strong> and repeats the process.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This cycle continues endlessly as long as the device remains powered.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 1/Level 1.4/Concept Building/images/What_happens_when_the_program_runs_0.png\" alt=\"What happens when the program runs\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Connecting everything together\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">At this point, multiple concepts come together to form a complete understanding of how the system works.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Setup</strong> prepares the system once at the beginning. <strong>Loop</strong> handles continuous execution after that. Inside <strong>Loop</strong>, the order of instructions defines the sequence of actions. Each instruction changes the state of the system, and <strong>delay</strong> controls how quickly these changes are observed.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Together, these concepts define the full behavior of the <strong>ESP32</strong> over time. A simple sequence inside the <strong>Loop</strong> can create continuous, repeating system behavior that runs indefinitely.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key insight of this lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Every <strong>ESP32</strong> program is built on a simple structure.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Setup</strong> runs once to prepare the system. <strong>Loop</strong> runs continuously to maintain system behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">All actions inside the system depend on where they are placed. Sequence defines order, state defines condition, and repetition inside the <strong>Loop</strong> defines continuous behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Understanding this structure is essential because it forms the foundation for every more advanced concept you will learn later.</p>\n        </div>\n        \n      </div>\n    ",
  "2-2-1": {},
  "2-2-1-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to make the <strong>ESP32</strong> send information to a screen using <strong>Serial</strong> communication.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will display messages and observe how your program communicates internally. This is the first time you will see how instructions you create can produce visible <strong>output</strong> without using physical components.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to display messages, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 can send information to a screen</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can observe what the program is doing internally</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a complete working system where your instructions produce visible informational <strong>output</strong> through the <strong>Serial</strong> Monitor.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.1/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "2-2-1-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is Serial Communication?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Serial</strong> communication is a method used by the <strong>ESP32</strong> to send data to another device, usually a computer.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of controlling physical components like LEDs or motors, the <strong>ESP32</strong> sends:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Text messages</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Numerical values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Status updates</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This communication happens in a sequence, one piece of data at a time, which is why it is called <strong>serial</strong> communication.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It creates a connection between:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 (sender)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The computer (receiver)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use simpler image</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.1/Concept Building/images/What_is_Serial_Communication__0.png\" alt=\"What is Serial Communication?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is the Serial Monitor?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>Serial</strong> Monitor is a tool that displays the data sent by the <strong>ESP32</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It acts as:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A display screen for your program</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A communication interface between you and the ESP32</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When the <strong>ESP32</strong> sends information, the <strong>Serial</strong> Monitor shows it instantly.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s you to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Read messages</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Observe changing values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Track program execution in real time</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Instead of this picture, can use serial monitor output picture</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.1/Concept Building/images/What_is_the_Serial_Monitor__0.png\" alt=\"What is the Serial Monitor?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Why Do We Use Serial Output?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Serial</strong> <strong>output</strong> is very important when working with embedded systems.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In many cases:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You cannot see what is happening inside the program</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">There is no physical output to observe</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You need to verify if your logic is correct</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Serial</strong> <strong>output</strong> helps solve this problem by:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Printing values and messages</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Showing step-by-step execution</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Helping identify errors or unexpected behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It is mainly used for:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Debugging programs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Testing logic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Understanding system behavior</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.1/Concept Building/images/Why_Do_We_Use_Serial_Output__0.png\" alt=\"Why Do We Use Serial Output?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What Type of Information Can Be Sent?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> can send different types of information through <strong>Serial</strong>, such as:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Simple messages (e.g., “System Started”)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sensor values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Input states (HIGH or LOW)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Program status updates</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes <strong>Serial</strong> communication a flexible and powerful tool.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What Happens When the Program Runs?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When your program runs, the fol<strong>low</strong>ing process occurs:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 starts executing instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">When it reaches a Serial block, it sends data</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The data travels from the ESP32 to the computer</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The Serial Monitor receives and displays the data</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program continues running and repeating this process</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Because the program runs continuously, the <strong>output</strong> is also updated continuously.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.1/Concept Building/images/What_Happens_When_the_Program_Runs__0.png\" alt=\"What Happens When the Program Runs?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Continuous Output and Repetition\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> does not send data just once.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It keeps sending data repeatedly as long as the program is running.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Messages may appear again and again</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Values may keep updating</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can observe changes over time</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This continuous behavior helps you monitor real-time activity.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How is Serial Output Different from LED Output?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">LED <strong>Output</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Physical</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Visible through light</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Limited to ON/OFF behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Serial</strong> <strong>Output</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Informational</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Visible as text</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Can show detailed data and messages</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Serial</strong> <strong>output</strong> gives you more control and more insight into your program.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Add a section highlighting how our app handle this in simple way (i have to add this properly first)</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can observe and understand your program’s internal behavior using <strong>Serial</strong> <strong>output</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are no longer limited to physical results.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You now have a way to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">See what the ESP32 is doing</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Track how it is working</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Debug and improve your programs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is a fundamental skill for building more advanced and interactive systems.</p>\n        </div>\n        \n      </div>\n    ",
  "2-2-2": {},
  "2-2-2-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to store and update values in your program using <strong>variables</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will use <strong>variables</strong> to keep track of information such as numbers, states, or sensor values. This is the first time you will see how your program can remember and update data during execution.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to store values, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Variables store information inside the program</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The stored values can be updated and used later</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where values are stored, updated, and used to control behavior, al<strong>low</strong>ing your programs to become more dynamic and intelligent.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/4.3/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "2-2-2-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 5.3: Variables (Storing and Updating Values)->>> (turned into 2.2 , needs increment and simulator examples)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is a <strong>Variable</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>variable</strong> is a place in the program where you can store a value.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can think of a <strong>variable</strong> as:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A container</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A box with a name</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This box stores information that your program can use.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store a number</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store a text message</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store a sensor value</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Why Do We Use <strong>Variables</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Variables</strong> are used to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store information</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Keep track of values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use data later in the program</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without <strong>variables</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You cannot remember values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You cannot update information</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">With <strong>variables</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Programs become dynamic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Values can change during execution</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Types of Variables</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Different types of <strong>variables</strong> store different kinds of data:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Integer (var_int) → stores whole numbers (e.g., 5, 10)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Float (var_float) → stores decimal numbers (e.g., 25.5)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">String (var_str) → stores text (e.g., \"Hello\")</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Boolean (var_bool) → stores TRUE or FALSE</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Choosing the correct type is important.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Storing a Value in a Variable</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">To store a value:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You create a variable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You assign a value to it</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store number 10 in a variable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store button state (HIGH/LOW)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Once stored:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program can use this value anytime</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Updating a Variable</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Variables</strong> are not fixed — they can be updated.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Start with value = 0</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Increase value by 1 each time</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is called updating a <strong>variable</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It al<strong>low</strong>s you to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Count things</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Track changes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store new values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Using Variables in Programs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Variables</strong> can be used to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store input values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use values in IF conditions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control outputs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store button state in a variable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use that variable to decide LED behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This connects:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Input → Variable → Condition → Output</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/4.3/Concept Building/images/LEVEL_5.3__Variables__Storing_and_Updating_Values_-_____turned_into_2.2___needs_increment_and_simulator_examples__0.png\" alt=\"LEVEL 5.3: Variables (Storing and Updating Values)->>> (turned into 2.2 , needs increment and simulator examples)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Example: Counter Using Variable\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Start counter at 0</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Increase by 1 each time</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Display value</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is useful for:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Counting repetitions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Tracking events</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Measuring activity</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Variables with Sensors</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Variables</strong> are very useful with sensors.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Read temperature from sensor</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Store it in a variable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use it in the program</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-world data to be used in logic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Smart decision making</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/4.3/Concept Building/images/Example__Counter_Using_Variable_0.png\" alt=\"Example: Counter Using Variable\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Variables</strong> al<strong>low</strong> you to store, update, and use information inside your program.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now able to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Remember values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Track changes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use data to control behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is essential for building dynamic, intelligent, and data-driven systems.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/4.3/Concept Building/images/LEVEL_5.3__Variables__Storing_and_Updating_Values_-_____turned_into_2.2___needs_increment_and_simulator_examples__2.png\" alt=\"Key Insight of This Lesson\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "2-2-3": {},
  "2-2-3-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to introduce <strong>input</strong> into your <strong>ESP32</strong> program using a button.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will use a button to send signals to the <strong>ESP32</strong> and observe how it detects user interaction. This is the first time you will see how external actions can affect the behavior of your program.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to use a button, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">External devices can send signals to the ESP32</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program can respond to user actions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where a physical action (button press) sends <strong>input</strong> to the <strong>ESP32</strong> and becomes part of the program’s behavior.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.2/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    <div class=\"border-t border-slate-100 my-8 pt-6\"></div>\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how the <strong>ESP32</strong> reads and understands <strong>input</strong> signals from a button.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will detect whether a button is pressed or not and observe how this information is represented inside the program. This is the first time you will see how physical actions are converted into digital values.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to read a button, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 reads electrical signals from inputs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Physical actions are converted into digital values (HIGH and LOW)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where the <strong>ESP32</strong> reads <strong>input</strong> states and represents them as values that can be used in your program.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "2-2-3-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is an Input?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">An <strong>input</strong> is any signal that is sent to the <strong>ESP32</strong> from an external device.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Inputs</strong> al<strong>low</strong> the <strong>ESP32</strong> to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Receive information</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Detect changes in the environment</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Respond to user actions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Examples of <strong>inputs</strong> include:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Buttons</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sensors</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Switches</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.2/Concept Building/images/What_is_an_Input__0.png\" alt=\"What is an Input?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is a Button?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A button is a simple <strong>input</strong> device used to send a signal to the <strong>ESP32</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It has two states:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Pressed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Not Pressed</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It is one of the most basic ways for a user to interact with a system.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.2/Concept Building/images/What_is_a_Button__0.png\" alt=\"What is a Button?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How Does a Button Work?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When a button is connected to a circuit:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">When pressed → the circuit is completed and a signal is sent</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">When not pressed → the circuit is open and no signal is sent</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> reads this electrical change through a <strong>pin</strong>.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.2/Concept Building/images/How_Does_a_Button_Work__0.png\" alt=\"How Does a Button Work?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Why Do We Need Inputs?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Inputs</strong> are important because they al<strong>low</strong> systems to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Respond to user actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Interact with the environment</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Change behavior dynamically</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without <strong>inputs</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system would only follow fixed instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">There would be no interaction</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.2/Concept Building/images/Why_Do_We_Need_Inputs__0.png\" alt=\"Why Do We Need Inputs?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> can receive signals from the outside world.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are no longer just controlling <strong>outputs</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are building systems that can detect and respond to user interaction.</p>\n        </div>\n        \n      </div>\n    <div class=\"border-t border-slate-100 my-8 pt-6\"></div>\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Concept Building/images/Continuous_Reading_and_Real-Time_Behavior_1.png\" alt=\"Concept Building\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What Does Reading Input Mean?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Reading <strong>input</strong> means checking the state of a <strong>pin</strong> connected to an external device, such as a button.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> does not understand actions like “pressed” or “not pressed” directly.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead, it:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Reads the electrical signal on the pin</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Determines its state</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Uses that value inside the program</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This process happens continuously while the program is running.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Concept Building/images/What_Does_Reading_Input_Mean__0.png\" alt=\"What Does Reading Input Mean?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What are HIGH and LOW?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>HIGH</strong> and <strong>LOW</strong> are the two possible digital states of a signal.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">HIGH means the signal is present (usually voltage is applied)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LOW means the signal is absent (no voltage)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These two states form the basis of digital systems.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can think of them as:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">HIGH → 1 (ON)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LOW → 0 (OFF)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">All digital systems, including the <strong>ESP32</strong>, work using these two values.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Concept Building/images/What_are_HIGH_and_LOW__0.png\" alt=\"What are HIGH and LOW?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How Does ESP32 Read a Button?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When a button is connected to a <strong>pin</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If the button is pressed → the pin reads HIGH</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If the button is not pressed → the pin reads LOW</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> continuously checks this <strong>pin</strong> and updates the value.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A physical press becomes a digital signal</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 converts real-world actions into data</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Concept Building/images/How_Does_ESP32_Read_a_Button__0.png\" alt=\"How Does ESP32 Read a Button?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          How is the Input Value Used?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Once the <strong>ESP32</strong> reads the <strong>input</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The value (HIGH or LOW) is stored</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This value can be used in the program</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It can control outputs or trigger actions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">HIGH → can be used to turn ON an LED</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LOW → can be used to turn OFF an LED</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is how <strong>input</strong> becomes useful in programming.</p>\n            <div class=\"my-4 flex items-start gap-3 rounded-xl border border-indigo-100 bg-indigo-50/50 p-4 text-sm text-indigo-900 shadow-sm\">\n              <span class=\"text-lg flex-shrink-0\">💡</span>\n              <div class=\"flex-1 leading-relaxed\">Note: If the yel<strong>low</strong> “? if “ blocks confuse you, don’t worry, they shall be explained in detail later.</div>\n            </div>\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Concept Building/images/How_is_the_Input_Value_Used__0.png\" alt=\"How is the Input Value Used?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Continuous Reading and Real-Time Behavior\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> does not read the <strong>input</strong> just once.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It continuously:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Reads the input</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Updates the value</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Reacts to changes</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates real-time behavior where:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Pressing the button immediately changes the system</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Releasing the button updates it again</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">3.6 Reading Temperature and Humidity with DHT11</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Not all <strong>inputs</strong> are simple <strong>HIGH</strong> or <strong>LOW</strong> signals. Some sensors, like the DHT11, provide more detailed data.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">First, you can set which sensor the <strong>pin</strong> is physically connected to:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The DHT11 sensor is used to measure:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Temperature</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Humidity</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of sending just <strong>HIGH</strong> or <strong>LOW</strong>, it sends digital data values that represent real-world measurements.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Temperature → 28°C</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Humidity → 65%</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> reads this data through a <strong>pin</strong> and converts it into meaningful information inside the program.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 is not only detecting actions (like a button press)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It can also measure environmental conditions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Our system al<strong>low</strong>s you to read these values and store them into <strong>variables</strong> (temp, humidity etc.) You can then use this information to perform a certain action based on the conditions of your environment.  An example use case can be a Smart Fan ; turn the fan on when the room gets hot and humid.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.3/Concept Building/images/Continuous_Reading_and_Real-Time_Behavior_0.png\" alt=\"Continuous Reading and Real-Time Behavior\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> converts physical actions into digital values (<strong>HIGH</strong> and <strong>LOW</strong>) that can be used in a program.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now able to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Detect user actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Represent them as data</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use that data to control behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is a critical step toward building interactive systems.</p>\n        </div>\n        \n      </div>\n    ",
  "2-2-4": {},
  "2-2-4-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to make decisions in your <strong>ESP32</strong> program using IF logic.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will use <strong>input</strong> values, such as a button state, to control what action the system performs. This is the first time you will see how your program can choose between different behaviors.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to use IF statements, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 can check conditions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program can take different actions based on those conditions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where the <strong>ESP32</strong> makes decisions and changes behavior depending on <strong>input</strong> values.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.4/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "2-2-4-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.4/Concept Building/images/Example_flow__1.png\" alt=\"Concept Building\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is Decision Making?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Decision making is the ability of the <strong>ESP32</strong> to choose between different actions based on a condition.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In earlier lessons:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 followed fixed instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The behavior was always the same</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 evaluates a condition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It selects what to do next</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s the system to behave differently in different situations.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is an IF Condition?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">An IF condition is a rule that checks whether something is true or false.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It creates a decision point in your program.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.4/Concept Building/images/What_is_Decision_Making__0.png\" alt=\"What is Decision Making?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Structure\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">IF condition is TRUE → execute one action</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ELSE → execute another action</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Only one path is executed at a time.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.4/Concept Building/images/Example_flow__3.png\" alt=\"Structure\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Conditions and Comparison\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A condition is based on comparing values.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Is the button <strong>HIGH</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Is a value equal to something?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These comparisons result in:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">TRUE</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">FALSE</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Button = HIGH → TRUE</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Button = LOW → FALSE</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This TRUE or FALSE result determines what action is taken.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.4/Concept Building/images/Conditions_and_Comparison_0.png\" alt=\"Conditions and Comparison\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Connecting Input to Decisions\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> uses <strong>input</strong> values inside IF conditions.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Example flow\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 reads the button state</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It checks: “Is the button HIGH?”</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If TRUE → it performs one action</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If FALSE → it performs another action</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">IF button is HIGH → LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ELSE → LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">From Decision to Behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Once decisions are introduced, the system’s behavior changes based on <strong>input</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a cause-and-effect relationship:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Cause → Button is pressed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Effect → LED turns ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Cause → Button is released</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Effect → LED turns OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> acts as the decision-maker that connects <strong>input</strong> to action.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When Button is Off:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When Button is On:</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 2/2.4/Concept Building/images/Example_flow__0.png\" alt=\"Example flow\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.6 Understanding System Behavior\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A system’s behavior is defined by how it:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Observes input</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Evaluates conditions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Executes actions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a structured f<strong>low</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Input → Condition → Action</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Because the <strong>ESP32</strong> keeps checking and updating:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system responds immediately</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The output reflects the latest input</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is why:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you press the button, the LED reacts instantly.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.7 Expanding the Same Logic\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This same idea can be extended to more complex systems.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">IF button1 is pressed → LED1 ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">IF button2 is pressed → LED2 ON</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Or:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">IF temperature is high → turn fan ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ELSE → keep fan OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This shows how simple logic can grow into real-world systems.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.8 From Simple Control to Smart Systems\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The system you built is a basic version of real-world smart systems.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This same pattern is used in:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Home automation</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Security systems</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Industrial control systems</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">All fol<strong>low</strong> the same structure:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Input → Condition → Action</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.9 Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> can evaluate conditions and change its behavior based on <strong>input</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now building systems that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Observe (input)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Decide (condition)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Act (output)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is the foundation of interactive and intelligent systems.</p>\n        </div>\n        \n      </div>\n    ",
  "3-3-1": {},
  "3-3-1-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          1. Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous levels, you worked with signals that had only two states:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ON or OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">HIGH or LOW</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">However, not all <strong>inputs</strong> in real-world systems behave this way.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Many <strong>inputs</strong> change continuously instead of switching between two fixed states.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will explore a new type of <strong>input</strong> where values are not limited to just two options. Instead, they can vary across a range.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will understand how the <strong>ESP32</strong> reads changing values and how these values behave over time.</p>\n        </div>\n        \n      </div>\n    ",
  "3-3-1-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 3/Level 3.1/Concept Building/images/3.2_1.png\" alt=\"Concept Building\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.1 What kind of values are you seeing?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A lot of sensors in real systems return data using analog signals.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means instead of giving simple ON or OFF values, they produce continuously changing signals that represent real-world conditions.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When you print the analog value, you will notice something different from digital <strong>input</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of seeing only:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">0 or 1</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will see a wide range of numbers.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These numbers continuously change as you interact with the sensor.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system is no longer reading simple states, it is reading real-world variation</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.2 What is an analog sensor?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">An analog sensor (<strong>input</strong>) is a device that converts a physical property into a continuous electrical signal.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this level, you are working with:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Photoresistor (Light Sensor)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Measures light intensity</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Bright light → higher or lower values depending on wiring</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Dark environment → opposite values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Potentiometer (Rotary Input)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Measures position of rotation</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Left side → low values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Right side → high values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Middle → medium values</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">These sensors do not give fixed results—they give a range of values based on physical change.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.3 How does the ESP32 read analog values?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>ESP32</strong> does not directly understand light, rotation or any other physical change.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead, It measures the <strong>input</strong> signal and converts it into numbers.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Some instances of this are:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Measures electrical resistance or voltage change</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Converts it into a numeric value</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Represents that value in a digital range</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.4 Understanding continuous change\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Unlike digital <strong>input</strong>, which jumps between two states, analog <strong>input</strong> changes smoothly.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">If you adjust the <strong>input</strong> s<strong>low</strong>ly:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The values change gradually</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">If you adjust it quickly:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The values change more rapidly</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a continuous stream of values that reflect the current condition of the <strong>input</strong>.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.5 What do the values represent?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each number represents a level of intensity:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Low value → low light / low position</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Medium value → moderate level</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">High value → strong light / full rotation</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">So instead of just simple ON / OFF states, You now have degrees of change</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is much closer to how the real world behaves.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.6 Understanding real-world sensors\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Different sensors represent different physical properties:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Photoresistor → light intensity</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Potentiometer → position</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Future sensors → temperature, pressure, distance</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">But they all share one key idea, they convert physical change into measurable values.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.7 Why range matters\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Analog values always stay within a fixed range.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For <strong>ESP32</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Minimum → 0</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Maximum → 4095</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">0 = lowest physical input</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">4095 = highest physical input</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Everything in between = intermediate states</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This range al<strong>low</strong>s the system to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Detect small changes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Represent fine variations</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Respond smoothly</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.8 Why values are not always stable\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You may notice small fluctuations even when the <strong>input</strong> seems unchanged.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This happens because:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Electrical signals are not perfectly stable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-world environments are noisy</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sensors are sensitive to small changes</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So slight variations are normal and expected.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.9 From physical world to data\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now your system works like this:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Physical change → Sensor → Electrical signal → Numeric value → ESP32</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is the foundation of all embedded systems.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.10 Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Analog sensors measure continuous physical changes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Photoresistors measure light</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Potentiometers measure position</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Values change smoothly, not in steps</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ESP32 converts physical signals into numeric ranges</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This enables precise measurement of real-world conditions</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 3/Level 3.1/Concept Building/images/3.1_0.png\" alt=\"3.10 Key Insight of This Lesson\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "3-3-2": {},
  "3-3-2-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          1. Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous lessons, you learned how to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Read continuously changing input values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Understand what those values represent</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So far, you have only observed data.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will take the next step:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will use values to control an <strong>output</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of turning an LED simply ON or OFF, you will now control how bright it is.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This introduces a new idea:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Outputs</strong> are not always binary. They can vary in intensity.</p>\n        </div>\n        \n      </div>\n    ",
  "3-3-2-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.1 Is the LED only ON or OFF?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In earlier lessons, the LED had only two states:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now you will notice something different.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The LED can:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Glow dimly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Glow moderately</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Glow brightly</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means the LED is no longer limited to two states. It can exist at different levels of brightness. This means the <strong>output</strong> is no longer binary—it is continuous.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.2 How is this possible?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 does not actually send “partial electricity.”</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead, it uses a technique called PWM (Pulse Width Modulation).</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It works by:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Switching the signal ON and OFF extremely fast</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">So fast that the human eye cannot detect it</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The result appears as different brightness levels</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So instead of changing electricity strength, it changes time patterns.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What matters for you is simple:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The value you provide controls how strong the <strong>output</strong> appears.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.3 What do the PWM values represent?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">PWM uses numbers to control intensity.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Typically:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Low values → weak output</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Medium values → balanced output</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">High values → strong output</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Low value → LED barely visible</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Medium value → LED clearly visible</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">High value → LED fully bright</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each value represents how much time the signal stays ON compared to OFF.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.4 Understanding gradual control\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Unlike digital <strong>output</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">PWM does not switch instantly between ON and OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It creates smooth transitions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When values change gradually:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Brightness increases step by step</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Brightness decreases step by step</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes the system feel natural and responsive.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.5 Why this is important\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Controlling intensity is essential in many real-world systems.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Adjusting brightness of lights</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Controlling motor speed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Regulating sound volume</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s systems to respond proportionally instead of just reacting with simple ON/OFF 3.5 Why this matters in real systems</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">PWM is used anywhere you need control instead of switching.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Examples:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Light dimming systems</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Fan speed control</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Motor speed regulation</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Audio volume control</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of only “ON/OFF”, systems can now behave proportionally.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.6 Connecting input and output (important shift)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now we connect what you learned in 3.1.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Use a sensor(photoresistor / potentiometer) to read and adjust values.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Convert that value into a usable range</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Use it to control <strong>output</strong> brightness of an LED.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a direct relationship:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Low sensor value → dim LED</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">High sensor value → bright LED</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You now have a dimmable LED that is responsive to the real world!</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.7 What you may notice in real behavior\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When using real sensor values:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Small changes in input cause small brightness changes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Large changes produce noticeable differences</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output feels smooth and continuous</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This shows that the system is not guessing—it is directly reacting to <strong>input</strong> values.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.8 Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Outputs are not limited to ON and OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">PWM allows smooth intensity control</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Values directly control output strength</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sensors can now drive physical output behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Systems move from switching → controlling</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This is the foundation of real-world embedded control</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    ",
  "3-3-3": {},
  "3-3-3-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          1. Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous lessons, you learned how to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Read analog input values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Understand their range (0 to 4095)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use values to control output intensity</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">However, when you try to directly use <strong>input</strong> values to control <strong>output</strong>, you may notice something does not behave correctly.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This happens because different parts of the system use different value ranges.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to translate values from one range to another so that systems can work correctly together.</p>\n        </div>\n        \n      </div>\n    ",
  "3-3-3-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3. Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.1 Why direct connection doesn’t work\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each sensor produces values in a large range.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Potentiometer → 0 to 4095</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Photoresistor → 0 to 4095 (varies with light conditions)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">But PWM <strong>output</strong> expects:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">0 to 255</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So if you connect them directly:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Most of the input range is not used properly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output reacts too quickly or too weakly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control feels inconsistent</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.2 Potentiometer: human control input\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The potentiometer is your manual control device.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It represents:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Human intention</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">User-controlled input</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">But raw values are too large for direct <strong>output</strong> control.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without conversion:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Small movements may cause big brightness jumps</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Large movements may feel unresponsive in parts</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.3 Photoresistor: environmental input\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The photoresistor represents the environment itself.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It does not respond to human <strong>input</strong>—it responds to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Light intensity</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Environmental changes</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without conversion:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Brightness control becomes unpredictable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output does not fully reflect light changes</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.4 What is mapping actually doing?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Map<strong>pin</strong>g converts a value from one range into another range while preserving its meaning.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It ensures:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Minimum input → minimum output</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Maximum input → maximum output</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Everything in between stays proportional</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So instead of raw values:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">0–4095 becomes 0–255</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s both systems to communicate correctly.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.5 Why proportional control matters\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Map<strong>pin</strong>g does not distort behavior—it preserves proportion.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">25% knob rotation → 25% brightness</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">50% light intensity → 50% output</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">75% input → 75% output</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes the system feel:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Predictable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Smooth</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Natural</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.6 What changes after mapping?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Before map<strong>pin</strong>g:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output reacts unevenly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Some ranges feel useless</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control feels inaccurate</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">After map<strong>pin</strong>g:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Full sensor range is usable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output changes smoothly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">System becomes responsive and stable</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.7 Connecting sensors and outputs properly\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now your system has a proper communication structure:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Potentiometer → manual brightness control</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Photoresistor → automatic brightness control</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Mapping → translation layer</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">PWM → physical output control</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is the first time your system behaves like a real control interface.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.8 Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sensors produce large-range values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Outputs require smaller, controlled ranges</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Direct connection breaks behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Mapping translates values between systems</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Proportional scaling preserves meaning</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">This enables accurate real-world control</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    ",
  "3-3-4": {},
  "3-3-4-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          1. Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In the previous lessons, you learned how to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Read analog input values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Understand their range</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control output intensity</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Translate values using mapping</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So far, these concepts were learned separately.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will combine everything to build a complete system where:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Input is continuously read</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Values are processed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Output responds immediately</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a real-time control system where one component directly controls another.</p>\n        </div>\n        \n      </div>\n    ",
  "3-3-4-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3. Concept Building\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.1 What kind of system have you built?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You now have two different control philosophies:</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Manual Control\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Human directly controls the system</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Potentiometer acts as an input device</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Behavior is intentional and predictable</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Automatic Control\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Environment controls the system</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Photoresistor reacts to light changes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Behavior depends on external conditions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is called a dual-mode control system.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.2 Manual control (Potentiometer system)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In manual mode:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The user decides brightness</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system follows user input directly</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">F<strong>low</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">👉 Potentiometer → Mapping → PWM → LED</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This gives:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Predictability</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Direct control</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Full user authority</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It is used in systems like:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Dimmers</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Volume knobs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Manual sliders</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.3 Automatic control (Photoresistor system)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In automatic mode:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The environment controls brightness</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system reacts to external light</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">F<strong>low</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">👉 Light → Photoresistor → Mapping → PWM → LED</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This gives:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Adaptive behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">No user input required</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Environment-driven response</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It is used in:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Auto-brightness screens</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Street lights</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Smart lighting systems</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.4 Why two modes matter\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Real systems are not fixed to one behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">They often switch between:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Manual override (user control)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Automatic behavior (system intelligence)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s flexibility depending on context.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">For example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">User adjusts brightness manually indoors</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">System adjusts automatically outdoors</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.5 Understanding control priorities\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In advanced systems:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Manual control usually has higher priority</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Automatic control runs when manual input is not active</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates layered behavior:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Primary control → user</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Secondary control → environment</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.6 What changes in system behavior?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Depending on mode:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Manual mode:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Stable and predictable</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Controlled by user actions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Automatic mode:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Dynamic and changing</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Controlled by environment</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This shows that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">👉 same hardware can behave differently based on logic</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.7 Connecting everything from Level 3\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now all Level 3 concepts merge:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Analog input → sensors read real-world values</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Mapping → values are normalized</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">PWM → output intensity control</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-time loop → continuous updates</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Two modes → behavioral switching layer</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This forms a complete embedded system structure.</p>\n        </div>\n        \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          3.8 Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Systems can have multiple control modes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Manual mode = user-driven behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Automatic mode = environment-driven behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Same hardware can behave differently using logic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Mapping and PWM enable both modes</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real systems switch between control strategies</span>\n            </li>\n          </ul>\n        </div>\n        \n      </div>\n    ",
  "4-4-1": {},
  "4-4-1-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to repeat actions automatically using repetition structures.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will use a <strong>for loop</strong> to make the <strong>ESP32</strong> perform the same action multiple times without writing the same instructions again. This is the first time you will see how your program can repeat tasks in a controlled way.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to repeat actions, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 can repeat instructions automatically</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can control how many times an action is repeated</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where a set of instructions runs multiple times using a <strong>loop</strong>, hel<strong>pin</strong>g you build efficient and structured programs.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.1/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-1-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Level 4.1: Repetition Structures (For Loop Basics)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.1/Concept Building/images/What_is_Repetition_in_Programming__0.png\" alt=\"Level 4.1: Repetition Structures (For Loop Basics)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          What is Repetition in Programming?\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Repetition means performing the same action multiple times.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In earlier lessons:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You wrote instructions once</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system executed them repeatedly automatically (loop)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You will control repetition intentionally</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can decide how many times something should repeat</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Repetition is useful when:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The same task needs to be done multiple times</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You want to avoid writing the same instructions again and again</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is a <strong>For Loop</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>for loop</strong> is a structure that repeats a set of instructions a specific number of times.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">It works using three main parts:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Start (Initialization) → where counting begins</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Condition → when the loop should stop</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Step (Increment) → how the count changes each time</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s the <strong>ESP32</strong> to repeat actions in a controlled way.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">How Does a <strong>For Loop</strong> Work?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>for loop</strong> fol<strong>low</strong>s a step-by-step process:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Start from an initial value (e.g., 0)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Check the condition (e.g., less than 5)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Execute the instructions inside the loop</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Increase the counter (e.g., +1)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat the process until the condition becomes false</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each repetition is called an iteration.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Why Do We Use <strong>For Loop</strong>s?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>For loop</strong>s are important because they:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Reduce repetition in code</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Make programs shorter and cleaner</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Save time and effort</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Improve readability</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without <strong>loop</strong>s:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You would need to write the same instructions many times</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">With <strong>loop</strong>s:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You write once and repeat automatically</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Example: Repeating LED Blink</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of writing:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Turn LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat manually</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can use a <strong>for loop</strong> to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Blink the LED 5 times automatically</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This shows how repetition can be controlled using <strong>loop</strong>s.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>for loop</strong> is used when we know exactly how many times we want an action to repeat. In this example, the <strong>loop</strong> is used to blink an LED 5 times without writing the same code again and again.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes programs:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">shorter,</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">easier to read,</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">and more efficient.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In our platform, the <strong>for loop</strong> can be represented using the “Repeat N Times” block.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>loop</strong> starts with a counter <strong>variable</strong> i = 0.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">After each repetition, the value of i increases by 1.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>loop</strong> continues running while the condition i < 5 remains true.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">During each repetition:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED turns ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program waits for 1 second</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The LED turns OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program waits for another 1 second</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The Serial Monitor prints the message \"Inside the loop\"</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">After the <strong>loop</strong> completes 5 repetitions, the condition becomes false and the program exits the <strong>loop</strong>. The remaining code then executes, printing \"Outside the <strong>loop</strong>\" on the <strong>Serial</strong> Monitor.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">void loop() {</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">for(int i=0; i<5; i++){</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">digitalWrite(2, HIGH); // LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">delay(1 * 1000);</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">digitalWrite(2, LOW); // LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">delay(1 * 1000);</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Serial.print(\"Inside the loop \");</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">}</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Serial.print(\"Outside the loop\");</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">}</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.1/Concept Building/images/What_is_Repetition_in_Programming__0.png\" alt=\"What is Repetition in Programming?\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Controlled vs Continuous Repetition\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">There are two types of repetition:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Continuous (Infinite Loop)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Runs forever (like previous loop behavior)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Controlled (For Loop)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Runs a specific number of times</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you are learning:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Controlled repetition using a for loop</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.1/Concept Building/images/What_is_Repetition_in_Programming__2.png\" alt=\"Controlled vs Continuous Repetition\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can control how many times an action is repeated using a <strong>for loop</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now able to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat actions efficiently</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control repetition using logic</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Build more structured programs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is a fundamental step toward writing advanced and optimized programs.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.1/Concept Building/images/What_is_Repetition_in_Programming__3.png\" alt=\"Key Insight of This Lesson\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-2": {},
  "4-4-2-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to repeat actions based on a condition using a <strong>while loop</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will create programs where the <strong>ESP32</strong> continues performing actions as long as a condition remains true. This is the first time you will see how repetition can depend on a condition instead of a fixed number.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to repeat actions, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 can repeat actions based on a condition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The repetition stops automatically when the condition becomes false</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where actions continue only while a condition is true, giving you more control over program behavior.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.2/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-2-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Level 5.2: Conditional Repetition (While Loop Basics)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is Conditional Repetition?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Conditional repetition means repeating an action based on a condition.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In previous lessons:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You used a for loop</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The repetition was fixed (e.g., repeat 5 times)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repetition depends on a condition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system decides whether to continue or stop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means the <strong>loop</strong> is not fixed — it depends on what is happening.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is a <strong>While Loop</strong>?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>while loop</strong> repeats a set of instructions as long as a condition is true.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Structure:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Check condition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If TRUE → execute instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If FALSE → stop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s the <strong>ESP32</strong> to keep running actions until something changes.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">How Does a <strong>While Loop</strong> Work?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>while loop</strong> works step-by-step:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Check the condition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If the condition is TRUE → run the instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Go back and check the condition again</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat the process</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Stop only when the condition becomes FALSE</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a <strong>loop</strong> controlled by a condition.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Difference Between For Loop and While Loop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">There are two types of repetition:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>For Loop</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Runs a fixed number of times</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You know how many repetitions will happen</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>While Loop</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Runs based on a condition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You do not know exactly how many times it will run</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This makes <strong>while loop</strong>s more flexible.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-Life Example of While Loop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Real-life example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Keep eating while you are hungry</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Stop when you are full</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Similarly:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ESP32 keeps running actions while condition is true</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Stops when condition becomes false</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Using While Loop with Inputs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The <strong>while loop</strong> is often used with <strong>inputs</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">While button is pressed → LED stays ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">When button is released → LED turns OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Try to guess how the code blocks can be arranged to achieve this interaction.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Heres how:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Code:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">void loop() {</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">btnState = digitalRead(12);</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">while(btnState == HIGH){</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">digitalWrite(2, HIGH); // LED ON</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">btnState = digitalRead(12);</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">}</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">digitalWrite(2, LOW); // LED OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">}</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates real-time control based on user interaction.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Risk of Infinite Loops</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>while loop</strong> can run forever if the condition never becomes false.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is called an infinite <strong>loop</strong>.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Condition is always TRUE → loop never stops</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">So it is important to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use correct conditions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Ensure the condition can change</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.2/Concept Building/images/misc_0.png\" alt=\"Level 5.2: Conditional Repetition (While Loop Basics)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A <strong>while loop</strong> repeats actions as long as a condition is true.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now able to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control repetition using conditions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Create flexible and dynamic systems</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Build real-time behavior based on input</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is a key step toward advanced logic and control structures.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.2/Concept Building/images/misc_1.png\" alt=\"Key Insight of This Lesson\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-3": {},
  "4-4-3-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to combine <strong>loop</strong>s and conditions to build more advanced logic in your programs.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will use repetition and decision-making together to control how the system behaves. This is the first time you will see how multiple programming concepts can work together to create smarter systems.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to use <strong>loop</strong>s or conditions separately, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loops repeat actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Conditions control those actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can combine both to create complex behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where actions are repeated and controlled by conditions, al<strong>low</strong>ing you to build more flexible and intelligent programs.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.4/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-3-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 5.4: Combining Logic (Loops + Conditions)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What Does Combining Logic Mean?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Combining logic means using multiple programming concepts together to control behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In earlier lessons:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You used loops (repetition)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You used conditions (decision making)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You combine both together</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system repeats actions and makes decisions at the same time</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates more powerful and flexible programs.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">How Do <strong>Loop</strong>s and Conditions Work Together?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When combined:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A loop repeats the process</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A condition controls what happens inside the loop</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">F<strong>low</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loop starts</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Input is read</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Condition is checked</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Action is executed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loop repeats</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system continuously checks and responds</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.4/Concept Building/images/misc_0.png\" alt=\"LEVEL 5.4: Combining Logic (Loops + Conditions)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Example: Button Controlled Loop Behavior\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loop runs continuously</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Inside the <strong>loop</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">IF button is pressed → LED blinks</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">ELSE → LED stays OFF</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This shows:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loop → keeps checking</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Condition → decides behavior</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.4/Concept Building/images/Example__Button_Controlled_Loop_Behavior_0.png\" alt=\"Example: Button Controlled Loop Behavior\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Nested Logic (Condition Inside Loop)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When a condition is placed inside a <strong>loop</strong>, it is called nested logic.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The loop runs repeatedly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The condition is checked in every iteration</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Continuous monitoring</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-time decision making</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Why is Combining Logic Important?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Combining logic is important because it al<strong>low</strong>s systems to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Continuously monitor inputs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Make decisions repeatedly</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">React instantly to changes</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Without combining logic:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Systems would be limited</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Behavior would not adapt dynamically</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">With combined logic:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Systems become interactive and intelligent</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-Time System Behavior</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">When <strong>loop</strong>s and conditions work together:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The system keeps running</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It keeps checking input</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">It keeps updating output</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Instant response</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Continuous interaction</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-time behavior</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Expanding Combined Logic</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This logic can be expanded:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Multiple conditions inside a loop</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Multiple inputs controlling different outputs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">More complex behaviors</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The fol<strong>low</strong>ing example demonstrates a double-check system. The light will only turn ON when both buttons are pressed. In this program, btn1 has priority because it is placed in the main condition.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This means:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The program first checks whether btn1 is pressed</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Only then does it check the state of btn2</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">If both conditions are true, the light turns ON</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">To test, lets just turn on btn2 alone:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The light remains OFF because the second condition is nested inside the first condition. The program cannot reach the btn2 check unless btn1 is already active.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This type of structure is called nested conditional logic, where one condition exists inside another condition.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now, when btn1 is pressed and then btn2 is pressed:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This shows how simple logic grows into complex systems.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.4/Concept Building/images/Nested_Logic__Condition_Inside_Loop__0.png\" alt=\"Nested Logic (Condition Inside Loop)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The most important concept in this lesson is:</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can combine <strong>loop</strong>s and conditions to create systems that continuously observe, decide, and act.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now able to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat actions continuously</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Make decisions inside repetition</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Build real-time interactive systems</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is a major step toward advanced programming and automation.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.4/Concept Building/images/Nested_Logic__Condition_Inside_Loop__3.png\" alt=\"Key Insight of This Lesson\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-4": {},
  "4-4-4-intro": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Introduction\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In this lesson, you will learn how to create patterns using LEDs by combining <strong>loop</strong>s, timing, and control logic.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You will design sequences where LEDs turn ON and OFF in a specific order, creating visible patterns. This is the first time you will see how your program can generate structured and creative behavior.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">The goal of this lesson is not just to blink LEDs, but to understand that:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Your blocks are instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">The ESP32 executes those instructions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can control the order of actions</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You can repeat sequences to form patterns</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">By the end of this lesson, you will have created a system where multiple instructions work together to produce repeating LED patterns, hel<strong>pin</strong>g you build more complex and visually interactive programs.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.5/Introduction/images/Introduction_0.png\" alt=\"Introduction\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    ",
  "4-4-4-concept": "\n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          LEVEL 5.5: Pattern Systems (Complex LED Patterns)\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Concept Building</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">What is a Pattern in Programming?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A pattern is a sequence of actions that repeats in a specific order.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">In earlier lessons:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You controlled a single LED</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You performed simple ON/OFF actions</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Now:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You will create organized sequences</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">These sequences repeat to form patterns</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">A pattern is not random — it fol<strong>low</strong>s a planned order.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">How Do Patterns Work?</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Patterns are created using:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A sequence of steps</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">A specific order of execution</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repetition of that sequence</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LED1 ON → LED1 OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LED2 ON → LED2 OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Repeat</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates a visible pattern.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Using Multiple Outputs</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">To create patterns, you often use multiple LEDs.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Each LED:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Is connected to a different pin</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Can be controlled independently</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This al<strong>low</strong>s:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Different LEDs to turn ON/OFF at different times</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">More complex and interesting patterns</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Role of Timing in Patterns</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Timing is very important in patterns.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Using <strong>delay</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Controls how long an LED stays ON or OFF</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Affects the speed of the pattern</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Short delay → fast pattern</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Long delay → slow pattern</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Timing makes patterns visible and meaningful.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Using Loops to Repeat Patterns</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\"><strong>Loop</strong>s are used to repeat patterns automatically.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Instead of writing the sequence many times:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">You define the pattern once</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Use a loop to repeat it</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Continuous patterns</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Efficient programs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Combining Logic for Complex Patterns</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Complex patterns are created by combining:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Multiple LEDs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Loops (repetition)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Timing (delay)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Conditions (optional)</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Example:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">LED1 → LED2 → LED3 → reverse sequence</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This creates advanced visual effects.</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Real-World Examples of Pattern Systems</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">Pattern systems are used in real life:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Traffic lights (Red → Yellow → Green)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Decorative lighting systems</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Car indicators (running lights)</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Display systems</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">All fol<strong>low</strong>:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Sequence + Timing + Repetition</span>\n            </li>\n          </ul>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.5/Concept Building/images/misc_0.png\" alt=\"LEVEL 5.5: Pattern Systems (Complex LED Patterns)\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          Key Insight of This Lesson\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          \n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.5/Concept Building/images/misc_1.png\" alt=\"Key Insight of This Lesson\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    \n      <div class=\"mb-6 rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:shadow-md transition-all duration-300\">\n        <h3 class=\"text-base font-bold text-slate-800 mb-3.5 flex items-center gap-2\">\n          <span class=\"inline-block w-2.5 h-2.5 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n          The most important concept in this lesson is\n        </h3>\n        <div class=\"text-slate-600 space-y-2\">\n          <p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You can create structured and repeating patterns by combining sequence, timing, and <strong>loop</strong>s.</p><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">You are now able to:</p><ul class=\"space-y-2 mb-4 pl-1\">\n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Control multiple outputs</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Create ordered sequences</span>\n            </li>\n          \n            <li class=\"flex items-start gap-2.5 text-slate-600 text-sm\">\n              <span class=\"mt-1.5 flex-shrink-0 w-2 h-2 rounded-full bg-cyan-500 shadow-sm shadow-cyan-300\"></span>\n              <span class=\"flex-1\">Build visually interactive systems</span>\n            </li>\n          </ul><p class=\"mb-3 leading-relaxed text-slate-600 text-sm\">This is an important step toward designing complex embedded systems and creative projects.</p>\n        </div>\n        \n        <div class=\"my-5 rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xl mx-auto bg-slate-50 transition-transform hover:scale-[1.01]\">\n          <img src=\"/lecs/levels/Level 4/4.5/Concept Building/images/misc_2.png\" alt=\"The most important concept in this lesson is\" class=\"w-full object-contain max-h-80\" />\n        </div>\n      \n      </div>\n    "
};
